112: /**
113:  * Parse the source string (`a, b`) to source list `['a', 'b']`.
114:  *
115:  * @param {import("@unblockneteasemusic/rust-napi").Executor} executor
116:  * @param {string} sourceString The source string.
117:  * @returns {string[]} The source list.
118:  */
119: function parseSourceStringToList(executor, sourceString) {
120:   const availableSource = executor.list();
121: 
122:   return sourceString
123:     .split(',')
124:     .map(s => s.trim().toLowerCase())
125:     .filter(s => {
126:       const isAvailable = availableSource.includes(s);
